import numpy as np

def gradient_descent(Q, b, x0, lr, steps):
    Q, b = np.asarray(Q, dtype=float), np.asarray(b, dtype=float)
    x = np.array(x0, dtype=float)            # a copy, so the caller's x0 is untouched
    path = [x.copy()]
    for _ in range(steps):
        x = x - lr * (Q @ x - b)
        path.append(x.copy())
    return np.array(path)
